namespace Shoal.Logging;

/// <summary>
///     Detail level for runtime crash dumps generated by the .NET runtime.
/// </summary>
public enum CrashDumpType
{
    /// <summary>Small dump containing threads, stacks, and loaded modules.</summary>
    Mini = 1,

    /// <summary>Dump containing process heap memory in addition to thread state.</summary>
    WithHeap = 2,

    /// <summary>Triage dump with sensitive user data filtered out.</summary>
    Triage = 3,

    /// <summary>Full memory dump of the crashing process.</summary>
    Full = 4,
}
